def _check_tdg1_frz1_result() -> list[str]:
    """Enforce TDG1's prospective, no-history diagnostic freeze."""

    path = REPOSITORY / "results/fgc-1-tdg1-frz1.json"
    try:
        source = path.read_text(encoding="utf-8")
        record = json.loads(source, object_pairs_hook=_reject_duplicate_json_pairs)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return [f"cannot inspect FGC-1-TDG1-FRZ1 certificate: {exc}"]
    canonical = json.dumps(record, indent=2, sort_keys=True, allow_nan=False) + "\n"
    payload = record.get("artifact_payload", {})
    lineage = payload.get("immutable_lineage", {})
    diagnostic = payload.get("frozen_diagnostic", {})
    synthetic = payload.get("synthetic_preflight", {})
    controls = synthetic.get("controls", {})
    mutations = payload.get("mutation_controls", {})
    boundary = payload.get("claim_boundary", {})
    successor = payload.get("successor_boundary", {})
    status = record.get("gate_status", {})
    expected_true = {
        "TDG1_diagnostic_contract_frozen",
        "TDG1_synthetic_counterexample_confirmed",
    }
    expected_false = {
        "inherited_normalized_raw_temporal_tail_ratio_is_valid_general_spatial_convergence_test",
        "TDG1_terminal_histories_diagnosed",
        "replacement_temporal_admission_defined",
        "PROTO14_frozen",
        "fresh_GR0_dynamic_calibration_completed",
        "GR0_case_eligible",
        "classical_spherical_diagnostic_authorized",
        "SGBL_execution_authorized",
        "FGCQR_holdout_execution_authorized",
        "FGCQR_mechanism_rejected",
        "retained_EFT_evolution_authorized",
        "physical_transition_claim_authorized",
        "general_gradient_route_rejected",
        "singularity_resolution_derived",
        "child_domain_or_topology_derived",
        "dark_sector_mechanism_derived",
        "varying_locally_measured_c_derived",
    }
    ledgers_pass = True
    for ledger_name in ("source_config_sha256", "implementation_sha256"):
        ledger = record.get(ledger_name, {})
        if not isinstance(ledger, dict) or not ledger:
            ledgers_pass = False
            continue
        for relative, expected in ledger.items():
            bound = REPOSITORY / str(relative)
            if (
                not bound.is_file()
                or sha256(bound.read_bytes()).hexdigest() != expected
            ):
                ledgers_pass = False
    document = REPOSITORY / str(record.get("derivation_document", ""))
    document_pass = (
        record.get("derivation_document") == "docs/fgc-tdg1-frz1.md"
        and document.is_file()
        and sha256(document.read_bytes()).hexdigest()
        == record.get("derivation_document_sha256")
    )
    checkpoint = (
        REPOSITORY
        / "runs/fgc-2-sf1/proto13/calibration/latest-checkpoint.npz"
    )
    # The raw campaign bundle is intentionally outside Git.  A clean clone
    # must still verify the compact certificate, while a locally present raw
    # checkpoint must match the immutable hash before it can support TDG1.
    checkpoint_pass = not checkpoint.exists() or (
        checkpoint.is_file()
        and sha256(checkpoint.read_bytes()).hexdigest()
        == "0432b266081b1ec1af3ac2a9efb99bcdd67dc8afef837241ec27fe5d37432f97"
    )
    control_names = (
        "zero",
        "constant",
        "affine",
        "low_sine",
        "smooth_pulse",
        "amplitude_scaled_low_sine",
    )
    synthetic_pass = (
        set(controls) == set(control_names)
        and controls.get("zero", {}).get("admission_passed") is True
        and controls.get("zero", {}).get("ratio_identity_verified") is True
        and all(
            controls.get(name, {}).get("every_individual_budget_passed") is True
            and controls.get(name, {}).get("every_nested_tail_ratio_passed")
            is False
            and controls.get(name, {}).get("admission_passed") is False
            and controls.get(name, {}).get("ratio_identity_verified") is True
            and controls.get(name, {}).get(
                "all_field_and_derivative_ratios_equal"
            )
            == 1.0
            for name in control_names[1:]
        )
        and controls.get("amplitude_scaled_low_sine", {}).get(
            "amplitude_sequence"
        )
        == [1.0, 0.25, 0.0625]
        and synthetic.get("structural_counterexample_confirmed") is True
        and synthetic.get("historical_threshold_unchanged") == 0.25
        and synthetic.get("mathematical_consequence")
        == "normalized_raw_temporal_tail_fractions_are_not_a_general_spatial_convergence_observable_for_nonzero_continuum_histories"
    )
    if (
        source != canonical
        or record.get("schema_version") != 1
        or record.get("artifact_id") != "FGC-1-TDG1-FRZ1"
        or record.get("project_version") != "0.11.0"
        or record.get("classification")
        != "prospective_TDG1_temporal_gate_diagnosis_freeze"
        or record.get("generated_by") != "scripts/reproduce_fgc_tdg1_frz1.py"
        or not ledgers_pass
        or not document_pass
        or not checkpoint_pass
        or set(status) != expected_true | expected_false
        or any(status.get(name) is not True for name in expected_true)
        or any(status.get(name) is not False for name in expected_false)
        or record.get("nonclaims")
        != {name: False for name in sorted(expected_false)}
        or lineage.get("checkpoint_commit")
        != "fa56acf4d8c6297eb6f9b5dc8afdb5e2b5ce9020"
        or lineage.get("checkpoint_commit_is_ancestor_of_HEAD") is not True
        or lineage.get("source_checkpoint_history_arrays_loaded") is not False
        or lineage.get("source_checkpoint_resumed") is not False
        or lineage.get("source_checkpoint_sha256")
        != "0432b266081b1ec1af3ac2a9efb99bcdd67dc8afef837241ec27fe5d37432f97"
        or diagnostic.get("sample_count") != 64
        or diagnostic.get("tracer_count") != 48
        or diagnostic.get("historical_maximum_nested_tail_ratio") != "1/4"
        or diagnostic.get("fixed_signal_views")
        != [
            "inherited_compact",
            "rectangular",
            "mean_centered_compact",
            "affine_detrended_compact",
        ]
        or not synthetic_pass
        or not isinstance(mutations, dict)
        or set(mutations.values()) != {True}
        or boundary
        != {
            "candidate_branch_opened": False,
            "historical_PROTO13_result_reclassified": False,
            "historical_threshold_changed": False,
            "new_trajectory_authorized": False,
            "raw_terminal_histories_diagnosed": False,
            "replacement_temporal_admission_defined": False,
        }
        or successor
        != {
            "TDG1_diagnostic_contract_frozen": True,
            "TDG1_actual_history_execution_authorized": True,
            "TDG1_actual_history_execution_completed": False,
            "replacement_temporal_gate_design_authorized": False,
            "PROTO14_frozen": False,
            "fresh_GR0_dynamic_calibration_completed": False,
            "GR0_case_eligible": False,
            "SGBL_execution_authorized": False,
            "FGCQR_holdout_execution_authorized": False,
            "DEF1_execution_authorized": False,
        }
    ):
        return [
            "FGC-1-TDG1-FRZ1 lineage, synthetic counterexample, prospective "
            "diagnostic contract, or closed claim boundary has drifted"
        ]
    return []


