def _check_tdg6_frz1_result() -> list[str]:
    """Enforce TDG6's prospective threshold freeze and nonpromotion boundary."""

    path = REPOSITORY / "results/fgc-1-tdg6-frz1.json"
    try:
        source = path.read_text(encoding="utf-8")
        record = json.loads(source, object_pairs_hook=_reject_duplicate_json_pairs)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return [f"cannot inspect FGC-1-TDG6-FRZ1 certificate: {exc}"]

    canonical = json.dumps(
        record,
        indent=2,
        sort_keys=True,
        ensure_ascii=True,
        allow_nan=False,
    ) + "\n"
    reproduction = subprocess.run(
        [
            sys.executable,
            "scripts/reproduce_fgc_tdg6_frz1.py",
            "--verify",
            "--output",
            "results/fgc-1-tdg6-frz1.json",
        ],
        cwd=REPOSITORY,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )

    payload = record.get("artifact_payload", {})
    lineage = payload.get("immutable_lineage", {})
    route = payload.get("selected_route", {})
    thresholds = payload.get("threshold_contract", {})
    ledger = payload.get("error_ledger", {})
    preflight = payload.get("exact_design_preflight", {})
    controls = preflight.get("controls", {})
    compositor = payload.get("production_compositor_contract", {})
    boundary = payload.get("claim_boundary", {})
    successor = payload.get("successor_boundary", {})
    mutations = payload.get("mutation_controls", {})
    proof = payload.get("proof_contract", {})

    implementation = record.get("implementation_sha256", {})
