def _check_tdg6_pref21_result() -> list[str]:
    """Enforce PREF21's independent binder and implementation-only boundary."""

    path = REPOSITORY / "results/fgc-1-tdg6-pref21.json"
    try:
        source = path.read_text(encoding="utf-8")
        record = json.loads(source, object_pairs_hook=_reject_duplicate_json_pairs)
    except (OSError, json.JSONDecodeError, ValueError) as exc:
        return [f"cannot inspect FGC-1-TDG6-PREF21 certificate: {exc}"]

    canonical = json.dumps(
        record,
        indent=2,
        sort_keys=True,
        ensure_ascii=True,
        allow_nan=False,
    ) + "\n"
    reproduction = subprocess.run(
        [
            sys.executable,
            "scripts/reproduce_fgc_tdg6_pref21.py",
            "--verify",
            "--output",
            "results/fgc-1-tdg6-pref21.json",
        ],
        cwd=REPOSITORY,
        stdout=subprocess.PIPE,
        stderr=subprocess.PIPE,
        text=True,
        check=False,
    )

    payload = record.get("artifact_payload", {})
    lineage = payload.get("immutable_lineage", {})
    binder = payload.get("independent_binder", {})
    quarter = binder.get("independent_quarter_restriction", {})
    interval = binder.get("independent_interval_order_theorem", {})
    channel = binder.get("independent_channel_debit_reduction", {})
    runtime = binder.get("immutable_runtime_extension_audit", {})
    crosscheck = payload.get("freeze_crosscheck", {})
    mutations = payload.get("mutation_controls", {})
    authorization = payload.get("implementation_authorization", {})
    limitations = payload.get("limitation_audit", {})
    proof = payload.get("proof_contract", {})
    successor = payload.get("successor_boundary", {})
    boundary = payload.get("claim_boundary", {})

    implementation = record.get("implementation_sha256", {})
    expected_implementation = {
        "configs/fgc/fgc-1-tdg6-pref21.toml",
        "docs/fgc-tdg6-pref21.md",
        "scripts/reproduce_fgc_tdg6_pref21.py",
        "src/recursive_horizons/fgc/evolution/tdg6_temporal_admission_theorem.py",
    }
    implementation_pass = set(implementation) == expected_implementation
    if implementation_pass:
        for relative, expected in implementation.items():
            bound = REPOSITORY / relative
            implementation_pass = implementation_pass and (
                bound.is_file()
                and sha256(bound.read_bytes()).hexdigest() == expected
            )

    lineage_pass = (
        lineage.get("freeze_commit")
        == "dff13cfc55e93124aa1fec3e350eae12dd0c6213"
        and lineage.get("freeze_commit_is_ancestor_of_HEAD") is True
        and lineage.get("freeze_result_verified_canonical_and_unimplemented")
        is True
        and lineage.get("raw_campaign_bundle_loaded") is False
        and isinstance(lineage.get("bound_source_sha256"), dict)
        and len(lineage.get("bound_source_sha256", {})) == 9
    )
    quarter_pass = (
        quarter.get("quarter_determinants") == ["1/4096"] * 4
        and quarter.get("all_quarter_determinants_are_1_over_4096") is True
        and quarter.get("direct_quarter_maps_equal_two_composed_half_maps") is True
        and quarter.get("all_basis_and_probe_controls_pass") is True
        and quarter.get("basis_control_count") == 16
        and quarter.get("four_quarter_maps_are_exact_and_injective") is True
    )
    interval_pass = (
        interval.get("minimum_observed_order") == "3/2"
        and interval.get("squared_multiplier_rederived_as_2_to_the_power_2p")
        == 8
        and interval.get("conservative_test") == "8*U12^2<=L01^2"
        and interval.get("universal_nonnegative_interval_implication") is True
        and interval.get("exact_boundary_passes") is True
        and interval.get("one_rational_unit_below_boundary_fails") is True
        and interval.get("exact_zero_passes_without_order_claim") is True
        and interval.get(
            "enclosure_dominated_passes_without_order_claim_and_retains_debit"
        )
        is True
        and interval.get("tiny_nonconvergent_pair_fails") is True
        and interval.get("order_inconclusive_pair_retries") is True
        and interval.get("no_absolute_magnitude_threshold_is_used") is True
        and interval.get("no_physical_signal_normalizes_the_test") is True
        and interval.get("controls_passed") is True
    )
    channel_pass = (
        channel.get("channel_count") == 18
        and len(channel.get("channel_order", [])) == 18
        and channel.get("all_of_reduction_passes_when_all_channels_pass") is True
        and channel.get("one_failed_channel_vetoes_complete_admission") is True
        and channel.get("finest_upper_bound_is_retained_per_channel") is True
        and channel.get(
            "accepted_debits_accumulate_by_componentwise_nonnegative_addition"
        )
        is True
        and channel.get("accumulation_uses_no_cancellation") is True
        and channel.get("formal_Richardson_division_is_not_used_for_admission_debit")
        is True
        and channel.get("debit_is_not_a_global_PDE_error_bound") is True
        and channel.get("future_observable_stability_map_remains_required") is True
        and channel.get("controls_passed") is True
    )
    runtime_pass = (
        runtime.get("TDG5_prepared_field_contract_present") is True
        and runtime.get(
            "TDG5_two_transaction_clones_and_three_shadow_attempts_present"
        )
        is True
        and runtime.get("TDG5_shadow_attempt_deliberately_has_no_tracer_preaccept")
        is True
        and runtime.get(
            "TDG5_prepare_preserves_real_monitor_causal_and_state_boundary"
        )
        is True
        and runtime.get(
            "TDG5_commit_revalidates_boundary_and_adopts_only_fine_monitor_causal_state"
        )
        is True
        and runtime.get("PROTO7_exposes_tracer_preview_commit_and_rollback_inputs")
        is True
        and runtime.get(
            "PROTO13_checkpoint_exposes_state_monitor_causal_and_tracer_extension_surface"
        )
        is True
        and runtime.get("TDG6_debit_and_temporal_retry_fields_are_not_yet_in_PROTO13")
        is True
        and runtime.get("production_compositor_extension_is_source_shape_feasible")
        is True
        and runtime.get("production_compositor_implemented") is False
        and runtime.get("production_trajectory_authorized") is False
    )
    binder_pass = (
        binder.get("all_independent_binder_controls_pass") is True
        and binder.get("TDG6_independent_binder_completed") is True
        and binder.get("production_compositor_implementation_authorized") is True
        and binder.get("production_compositor_implemented") is False
        and binder.get("PROTO14_frozen") is False
        and binder.get("fresh_GR0_dynamic_calibration_completed") is False
        and binder.get("GR0_case_eligible") is False
        and binder.get("actual_PROTO13_history_arrays_consumed") is False
        and binder.get("campaign_checkpoint_loaded") is False
        and binder.get("campaign_checkpoint_resumed") is False
        and binder.get("production_state_advanced") is False
        and binder.get("SGBL_trajectory_read") is False
        and binder.get("FGCQR_trajectory_read") is False
        and binder.get("physical_or_candidate_question_answered") is False
    )
    authorization_pass = (
        authorization.get("production_trajectory_authorized") is False
        and authorization.get("historical_PROTO13_stop_preserved") is True
        and authorization.get("historical_CAL10_result_reclassified") is False
        and authorization.get("threshold_or_protocol_mutation_authorized") is False
        and authorization.get(
            "only_complete_four_quarter_step_path_is_committable"
        )
        is True
        and authorization.get(
            "fine_state_monitor_causal_tracer_and_debit_ledgers_commit_atomically"
        )
        is True
        and authorization.get(
            "checkpoint_must_round_trip_debit_retry_and_rejection_ledgers"
        )
        is True
    )
    successor_pass = (
        successor.get("TDG6_independent_binder_completed") is True
        and successor.get("production_compositor_implementation_authorized")
        is True
        and successor.get("production_compositor_implemented") is False
        and successor.get("PROTO14_frozen") is False
        and successor.get("fresh_GR0_dynamic_calibration_completed") is False
        and successor.get("GR0_case_eligible") is False
        and successor.get("SGBL_execution_authorized") is False
        and successor.get("FGCQR_holdout_execution_authorized") is False
        and successor.get("DEF1_execution_authorized") is False
    )
    boundary_pass = (
        boundary.get("TDG6_independent_binder_completed") is True
        and boundary.get("production_compositor_implementation_authorized") is True
        and boundary.get("production_compositor_implemented") is False
        and boundary.get("PROTO14_frozen") is False
        and boundary.get("fresh_GR0_dynamic_calibration_completed") is False
        and boundary.get("GR0_case_eligible") is False
        and boundary.get("classical_spherical_diagnostic_authorized") is False
        and boundary.get("SGBL_execution_authorized") is False
        and boundary.get("FGCQR_holdout_execution_authorized") is False
        and boundary.get("FGCQR_mechanism_rejected") is False
        and boundary.get("retained_EFT_evolution_authorized") is False
        and boundary.get("physical_transition_claim_authorized") is False
        and boundary.get("general_gradient_route_rejected") is False
    )

    if (
        source != canonical
        or reproduction.returncode != 0
        or record.get("schema_version") != 1
        or record.get("artifact_id") != "FGC-1-TDG6-PREF21"
        or record.get("project_version") != "0.11.0"
        or record.get("classification")
        != "independent_temporal_admission_binder_and_runtime_implementation_authorization"
        or record.get("gate_status")
        != "PASS_PRODUCTION_COMPOSITOR_IMPLEMENTATION_AUTHORIZED"
        or record.get("generated_by") != "scripts/reproduce_fgc_tdg6_pref21.py"
        or record.get("source_config_sha256")
        != implementation.get("configs/fgc/fgc-1-tdg6-pref21.toml")
        or record.get("derivation_document") != "docs/fgc-tdg6-pref21.md"
        or record.get("derivation_document_sha256")
        != implementation.get("docs/fgc-tdg6-pref21.md")
        or not implementation_pass
        or not lineage_pass
        or not quarter_pass
        or not interval_pass
        or not channel_pass
        or not runtime_pass
        or not binder_pass
        or not authorization_pass
        or not successor_pass
        or not boundary_pass
        or not isinstance(crosscheck, dict)
        or set(crosscheck.values()) != {True}
        or not isinstance(mutations, dict)
        or set(mutations.values()) != {True}
        or not isinstance(limitations, dict)
        or set(limitations.values()) != {True}
        or not isinstance(proof, dict)
        or set(proof.values()) != {True}
    ):
        detail = reproduction.stderr.strip()
        suffix = f": {detail}" if detail else ""
        return [
            "FGC-1-TDG6-PREF21 lineage, independent theorem, runtime "
            f"feasibility, or implementation-only boundary has drifted{suffix}"
        ]
    return []


